const e = $('Flow Workflow Failed').first().json;
const s = $json;
const esc = function (v) { return String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
const ex = e.execution || {};
const wf = e.workflow || {};
const err = ex.error || e.trigger && e.trigger.error || {};
const html = '<p><b>' + esc(wf.name || 'A Flow workflow') + '</b> failed at ' + $now.toFormat('ccc d LLL, h:mm a') + '.</p>' +
  '<table cellpadding="4"><tr><td>Step</td><td>' + esc(ex.lastNodeExecuted || 'unknown') + '</td></tr><tr><td>Error</td><td>' + esc(String(err.message || 'No message').slice(0, 500)) + '</td></tr><tr><td>Mode</td><td>' + esc(ex.mode || '') + '</td></tr></table>' +
  (ex.url ? '<p><a href="' + esc(ex.url) + '">Open the failed run in n8n</a></p>' : '') +
  '<p style="color:#666">Flow error alert. Customer data is not included in this email.</p>';
return [{ json: { to: s.ops_email || s.owner_email, from: s.from_address, subject: '[Flow error] ' + (wf.name || 'Workflow') + ': ' + String(err.message || 'failed').slice(0, 80), html: html } }];
